<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/database.php';
$orders = readOrders();
$total = count($orders);
$pending = count(array_filter($orders, static fn (array $order): bool => in_array($order['status'] ?? '', ['Nouvelle', 'En préparation'], true)));
$ready = count(array_filter($orders, static fn (array $order): bool => ($order['status'] ?? '') === 'Prête'));
$revenue = array_sum(array_map(static fn (array $order): float => (float) ($order['total'] ?? 0), $orders));
function euro(float $value): string { return number_format($value, 2, ',', ' ') . ' €'; }
